import React from 'react';
import { IncidentDetection, IncidentDetectionStatus } from '../../../models/IncidentDetection';
import { useResponsive } from '../../../hooks/useResponsive';
import styles from './DetectionTable.module.css';
import { Button, TwoLineTable, TwoLineTableColumn, TwoLineTableRow } from '@linm-soft-org/linm-web-common-components';

interface Props {
  items: IncidentDetection[];
  loading?: boolean;
  onView: (item: IncidentDetection) => void;
  label: (key: string) => string;
  statusLabel: (status: string) => string;
}

const BADGE_CLS: Record<string, string> = {
  [IncidentDetectionStatus.Draft]: styles.badgeDraft,
  [IncidentDetectionStatus.Routed]: styles.badgeRouted,
  [IncidentDetectionStatus.Claimed]: styles.badgeClaimed,
  [IncidentDetectionStatus.Converted]: styles.badgeConverted,
  [IncidentDetectionStatus.Rejected]: styles.badgeRejected,
  [IncidentDetectionStatus.Cancelled]: styles.badgeCancelled,
};

const fmt = (iso: string | null | undefined) =>
  iso
    ? new Date(iso).toLocaleString('vi-VN', {
      day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit',
    })
    : '—';

export const DetectionTable: React.FC<Props> = ({ items, loading, onView, label, statusLabel }) => {
  const { isMobile } = useResponsive();

  const columns: TwoLineTableColumn[] = [
    { key: 'detectedAt', label: label('colDetectedAt'), width: '25%' },
    { key: 'department', label: label('colDepartment'), width: '25%' },
    { key: 'detector', label: label('colDetector'), width: '25%' },
    { key: 'status', label: label('colStatus'), width: '25%' },
  ];

  const rows: TwoLineTableRow<IncidentDetection>[] = items.map((item) => ({
    id: item.id,
    data: item,
    idElement: <span className={styles.idCode}>{item.idCode}</span>,
    line1Content: (
      <>
        <span className={styles.desc}>{item.description || <em className={styles.na}>—</em>}</span>
        <span className={`${styles.badge} ${BADGE_CLS[item.status] ?? styles.badgeDraft}`}>
          {statusLabel(item.status)}
        </span>
      </>
    ),
    line2Cells: [
      <span>{fmt(item.detectedAt)}</span>,
      <span>{item.targetDepartmentName || <em className={styles.na}>—</em>}</span>,
      <span>{item.detectorUserName}</span>,
      <span>{statusLabel(item.status)}</span>,
    ],
    actionsContent: (
      <div className={styles.actions}>
        <Button variant="secondary" onClick={() => onView(item)}>
          <i className="fas fa-eye" /> {label('view')}
        </Button>
      </div>
    ),
  }));

  return (
    <TwoLineTable
      columns={columns}
      rows={rows}
      loading={loading}
      emptyMessage={{
        icon: 'fas fa-camera',
        title: label('emptyTitle'),
        description: label('emptyDesc'),
      }}
      expandableActions
      isMobile={isMobile}
    />
  );
};
